INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷79·晋高祖纪·天福五年四月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c30e8592e48c53567d2d07454baccf80e3e0ec55/content/books/zizhi-tongjian/vol-282/year-0940/part-01/sources/library/jiuwudaishi-079-april/source.txt", "note": "《旧五代史》卷79·晋高祖纪·天福五年四月，段落 jiu-wudaishi-205deb4a7860-p001945；已核上下文及传主，纸本及异文待核。", "id": "0d7cfbde-b9e9-5c61-a06a-0fda97fcfe76"}, {"title": "旧五代史·卷79·晋高祖纪·天福五年二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c30e8592e48c53567d2d07454baccf80e3e0ec55/content/books/zizhi-tongjian/vol-282/year-0940/part-01/sources/library/jiuwudaishi-079-february/source.txt", "note": "《旧五代史》卷79·晋高祖纪·天福五年二月，段落 jiu-wudaishi-205deb4a7860-p001943；已核上下文及传主，纸本及异文待核。", "id": "eb1687c3-e0dc-5c6c-96ec-197d2d0e13a6"}, {"title": "旧五代史·卷79·晋高祖纪·天福五年三月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c30e8592e48c53567d2d07454baccf80e3e0ec55/content/books/zizhi-tongjian/vol-282/year-0940/part-01/sources/library/jiuwudaishi-079-march/source.txt", "note": "《旧五代史》卷79·晋高祖纪·天福五年三月，段落 jiu-wudaishi-205deb4a7860-p001944；已核上下文及传主，纸本及异文待核。", "id": "aa609fa5-dc83-584b-8c11-39e39db2bbf8"}, {"title": "资治通鉴·卷282·天福五年春夏", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c30e8592e48c53567d2d07454baccf80e3e0ec55/content/books/zizhi-tongjian/vol-282/year-0940/part-01/sources/library/tongjian-282-940-spring/source.txt", "note": "《资治通鉴》卷282·天福五年春夏，段落 zizhi-tongjian-a63549944a71-p003352；已核上下文及传主，纸本及异文待核。", "id": "f1900b5e-ea31-5aca-8cf7-9f5082103413"}, {"title": "新五代史·卷66·楚世家·彭士愁归降与铜柱", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c30e8592e48c53567d2d07454baccf80e3e0ec55/content/books/zizhi-tongjian/vol-282/year-0940/part-01/sources/library/xinwudaishi-066-chu-surrender/source.txt", "note": "《新五代史》卷66·楚世家·彭士愁归降与铜柱，段落 xin-wudaishi-b08f244b9241-p003324；已核上下文及传主，纸本及异文待核。", "id": "fb27d490-d1c2-55ce-8344-e586acc8e2d3"}, {"title": "新五代史·卷68·闽世家·王延政", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c30e8592e48c53567d2d07454baccf80e3e0ec55/content/books/zizhi-tongjian/vol-282/year-0940/part-01/sources/library/xinwudaishi-068-min-conflict/source.txt", "note": "《新五代史》卷68·闽世家·王延政，段落 xin-wudaishi-b08f244b9241-p003412；已核上下文及传主，纸本及异文待核。", "id": "a70e38ed-216f-56c3-b148-1d359e65b0ec"}, {"title": "资治通鉴·后晋纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/edf81ef2a20318750c60f3a1d5fdfb06de275ef4/content/books/zizhi-tongjian/vol-282/year-0939/part-04/sources/library/tongjian-282-939-autumn/source.txt", "note": "《资治通鉴》后晋纪三，段落 zizhi-tongjian-a63549944a71-p003351；电子底本待考，分段待核", "id": "ae1a99c8-e99c-5cab-8102-be9be479d9f7"}, {"title": "旧五代史·卷133·马希范传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/edf81ef2a20318750c60f3a1d5fdfb06de275ef4/content/books/zizhi-tongjian/vol-282/year-0939/part-04/sources/library/jiuwudaishi-133-ma-xifan/source.txt", "note": "《旧五代史》卷133·马希范传，段落 jiu-wudaishi-205deb4a7860-p003141；已核上下文及传主，纸本及异文待核。", "id": "59353483-fe28-5a46-841a-f4fc2358b3bc"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "郑元弼", "aliases": ["鄭元弼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国礼部员外郎。939年奉王继恭的表章，随卢损前往后晋进贡。生卒年未载。", "biography": null, "status": "draft", "id": "a656f099-5f42-574b-bfa0-daa89cb73913"}, {"name": "刘勍", "aliases": ["劉勍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国左静江指挥使。939年九月与决胜指挥使廖匡齐率衡山兵五千讨伐彭士愁。生卒年未载。", "biography": null, "status": "draft", "id": "f3436028-6ef5-568c-a1c1-0bec76b0ccb3"}, {"name": "彭士愁", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "溪州刺史。939年率蒋州、锦州部众一万多人进攻辰州、澧州，并向后蜀求援，未获同意。生卒年未载。", "biography": null, "status": "draft", "id": "a28c6cdb-75c0-5abc-8757-6d971634ad02"}, {"name": "彭师暠", "aliases": ["彭師暠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "彭士愁的儿子。940年受父亲派遣，率诸酋长向楚交出溪、锦、奖三州官印，请求归降。生卒年未载。", "biography": null, "status": "draft", "id": "9a01204b-6429-53ed-8ca1-76b3143bd4d8"}, {"name": "安彦威", "aliases": ["安彥威"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安彦威，侍卫马军都指挥使、宁国节度使。", "biography": null, "status": "draft", "id": "fe8191f2-7077-5aac-806f-7a165fcf9b34"}, {"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "杨琏", "aliases": ["楊璉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成三年条所见人物：杨琏，获封江都王者。", "biography": null, "status": "draft", "id": "4975dc84-c87f-5d7f-b1e7-3254e45440ea"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "王审知", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加封钱镠、张全义、刘隐等”中为受授者。", "biography": null, "status": "draft", "id": "099c16ed-15be-506b-a65f-aa94c272cbd8"}, {"name": "业翘（闽监军）", "aliases": ["业翘", "業翹"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延羲派往建州监督军队的亲吏，与王延政发生争执后逃往南镇，后来与杜汉崇逃往福州。姓名沿《资治通鉴》业翘，不与叶翘自动合并。生卒年未载。", "biography": null, "status": "draft", "id": "e633cc16-042a-56d1-aa4f-bd727cec2974"}, {"name": "杜汉崇", "aliases": ["杜漢崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国教练使，受王延羲派遣监督南镇军，与业翘一起向王延羲报告王延政的隐事，随后逃往福州。《新五代史》相关故事中的监军名为杜建崇，姓名差异待核。生卒年未载。", "biography": null, "status": "draft", "id": "7469922f-5fc4-552c-884f-fdabf41c8882"}, {"name": "潘师逵", "aliases": ["潘師逵"], "era": "五代十国", "birth_year": null, "death_year": 940, "description": "闽国统军使。940年与吴行真率军进攻王延政，驻建州城西；三月遭王延政夜袭，被陈诲杀死。出生年未载。", "biography": null, "status": "draft", "id": "289845a5-a71e-5461-9329-0b806d4cf1e2"}, {"name": "吴行真", "aliases": ["吳行真"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国统军使。940年与潘师逵率军进攻王延政，驻建州城南；三月在王延政军队渡水进攻以前弃营逃走。生卒年未载。", "biography": null, "status": "draft", "id": "6c0f363c-943d-5349-af4d-9e1250b13cb8"}, {"name": "钱传瓘", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为出征者。", "biography": null, "status": "draft", "id": "6674e6a1-d66d-5e57-af1f-2d98f55021a1"}, {"name": "仰仁诠", "aliases": ["仰仁詮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：仰仁诠，受遣牙将。", "biography": null, "status": "draft", "id": "bb229efa-8831-569a-84b2-c48d86bee7a7"}, {"name": "薛万忠", "aliases": ["薛萬忠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越内都监使。940年与仰仁诠受钱传瓘派遣，率军救援建州的王延政。生卒年未载。", "biography": null, "status": "draft", "id": "11246a77-d93a-5158-ac5d-98e85b5a0666"}, {"name": "林鼎", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越官员。937年以镇海节度判官身份掌管教令。", "biography": null, "status": "draft", "id": "f7c11336-2f57-5c43-9ea1-538c76c4b27d"}, {"name": "蔡弘裔", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国都军使。940年三月受潘师逵派遣，带三千兵出战，被王延政派出的林汉彻等在茶山击败。生卒年未载。", "biography": null, "status": "draft", "id": "57a62618-6ca3-549a-a1ba-9932762d4a50"}, {"name": "林汉彻", "aliases": ["林漢徹"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政麾下将领。940年三月与其他将领在茶山击败蔡弘裔所率军队。生卒年未载。", "biography": null, "status": "draft", "id": "1ad8b8e8-2b44-59e7-9e4e-9263d67673a1"}, {"name": "王建立", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：王建立。", "biography": null, "status": "draft", "id": "2addb586-2a21-57fe-a7f1-0f93cd12ebdd"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "李德珫", "aliases": ["李德充"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋建雄节度使。940年三月调任北都留守。《旧五代史》同次从晋州到北京的调任写作李德充，按任职与行动对应识别为同一人，保留原文字形说明。生卒年未载。", "biography": null, "status": "draft", "id": "0263c149-1d66-5360-8ad2-9b565aa3d34e"}, {"name": "皇甫遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：皇甫遇，原严卫步军都指挥使、接侍卫步军者。", "biography": null, "status": "draft", "id": "0aa52fa6-cacc-5960-8646-9ab3a0393623"}, {"name": "安从进", "aliases": ["安從進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安从进，受询的侍卫都指挥使。", "biography": null, "status": "draft", "id": "3b1f48e5-6ce0-58cd-add7-1bdf9f0d4812"}, {"name": "王令谦", "aliases": ["王令謙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安从进的元随都押牙，因劝谏安从进被杀。史书未在此处明确劝谏与遇害的具体年份。", "biography": null, "status": "draft", "id": "9b41a496-3cc4-56f2-97f4-844cae0d881a"}, {"name": "潘知麟", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安从进麾下押牙，因劝谏安从进被杀。史书未在此处明确劝谏与遇害的具体年份。", "biography": null, "status": "draft", "id": "07d5bcdd-1bc5-5e3d-8d89-a6e2d723031b"}, {"name": "陈诲", "aliases": ["陳誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "建安人，王延政麾下战棹都头。940年三月在夜袭中杀死潘师逵。生卒年未载。", "biography": null, "status": "draft", "id": "8c18058e-c4f8-52ab-a4d2-9caaba34336a"}, {"name": "赵季良", "aliases": ["趙季良"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271龙德二年条所见人物：赵季良。", "biography": null, "status": "draft", "id": "5cccbc59-1a95-5072-a1b8-d769fd075712"}, {"name": "毋昭裔", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：毋昭裔，龙门人、原御史中丞、获任宰辅者。", "biography": null, "status": "draft", "id": "4d43c16a-22c8-593d-ba83-347e273efd9a"}, {"name": "张业", "aliases": ["張業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张业。", "biography": null, "status": "draft", "id": "79f0f8ee-f0c7-5ba0-a428-aacf648664be"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "马全节", "aliases": ["馬全節"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马全节，金州防御使、以私财给军并拒战者。", "biography": null, "status": "draft", "id": "bb5608d9-eabe-58ce-8c56-b07e57faadb5"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
