940年正月条下，具体日期未载", "dynasty": "五代十国", "description": "彭士愁率部逃入奖州、锦州深山。", "phases": [], "location_name": "奖州、锦州深山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "16d22438-66f3-57f7-8ed9-3ec7355853a7"}, {"title": "彭士愁派彭师暠交出三州官印，请求归降楚国", "start_year": 940, "end_year": 940, "time_original": "940年正月乙未", "dynasty": "五代十国", "description": "彭士愁派儿子彭师暠率诸酋长，向楚交出溪、锦、奖三州官印，请求归降。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1b955ebb-b889-57a3-a917-219181159efe"}, {"title": "安彦威入朝，石敬瑭赞许他对契丹谦让", "start_year": 940, "end_year": 940, "time_original": "940年二月庚戌", "dynasty": "五代十国", "description": "北都留守安彦威入朝。石敬瑭说，契丹曾援救自己，现在应以信义相报，并赞许安彦威在契丹不断索求时仍能谦让。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "309b02e6-7198-563e-ac44-9745628606c1"}, {"title": "安彦威回应，皇帝为百姓尚且谦让，自己更应如此", "start_year": 940, "end_year": 940, "time_original": "940年二月庚戌", "dynasty": "五代十国", "description": "安彦威回应说，皇帝为百姓尚且以谦辞和厚礼侍奉契丹，自己谦让又有什么可说。石敬瑭听后高兴。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "49a25cf4-6592-52ca-a372-5430c61dcfe1"}, {"title": "刘勍率军返回长沙", "start_year": 940, "end_year": 940, "time_original": "940年二月条下，具体日期未载", "dynasty": "五代十国", "description": "刘勍率军返回长沙。", "phases": [], "location_name": "长沙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fb2ac975-83f8-5882-9e2d-d54b91dfd1e9"}, {"title": "马希范迁溪州治所，并奏请彭士愁担任溪州刺史", "start_year": 940, "end_year": 940, "time_original": "940年二月条下，具体日期未载", "dynasty": "五代十国", "description": "马希范把溪州迁到较便利的地方，并上表请求让彭士愁担任溪州刺史。", "phases": [], "location_name": "溪州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f8586f21-d927-56ce-9cf9-a4f5026c87e1"}, {"title": "马希范任刘勍为锦州刺史，此后当地部众服从楚国", "start_year": 940, "end_year": 940, "time_original": "940年二月条下，具体日期未载", "dynasty": "五代十国", "description": "马希范任刘勍为锦州刺史。《资治通鉴》随后记当地部众归服楚国。", "phases": [], "location_name": "锦州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "044fd202-fddc-5608-b86b-eb56d4227d8c"}, {"title": "马希范在溪州铸立铜柱，刻上盟誓", "start_year": 940, "end_year": 940, "time_original": "940年二月条下，具体日期未载", "dynasty": "五代十国", "description": "马希范自称伏波将军的后裔，用五千斤铜铸柱，柱高一丈二尺，入地六尺，在柱上刻下盟誓并立在溪州。", "phases": [], "location_name": "溪州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e5d2557e-5d94-5981-978d-f0650bd922f9"}, {"title": "杨琏祭谒平陵归来后，在船上醉后去世", "start_year": 940, "end_year": 940, "time_original": "940年二月条下，具体日期未载", "dynasty": "五代十国", "description": "康化节度使兼中书令杨琏祭谒平陵归来，一天夜里大醉，随后在船中去世。", "phases": [], "location_name": "归途船中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f4e49537-acc9-558d-adbd-0c6632418818"}, {"title": "李昪追封杨琏为弘农靖王", "start_year": 940, "end_year": 940, "time_original": "940年二月条下，具体日期未载", "dynasty": "五代十国", "description": "李昪追封杨琏为弘农靖王。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null